# Output: 1s stay 1, non-1/0 becomes column's 1-count
output_col1 = [[1 if v == 1 else sum(1 for x in row if x == 1) for v in row] for row in input_grid]
print("Column-based (just row 1 counts):")
for row in output_col1:
    print(' '.join(f'{v:2}' for v in row))

# Another idea: maybe non-1 becomes count of its 1-neighbors
def count_1_neighbors(grid, r, c):
    count = 0
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r+dr, c+dc
        if 0 <= nr < 7 and 0 <= nc < 7 and grid[nr][nc] == 1:
            count += 1
    return count

output_neighbor = []
for row in input_grid:
    new_row = []
    for v in row:
        if v == 1:
            new_row.append(1)
        elif v == 0:
            new_row.append(0)
        else:
            new_row.append(count_1_neighbors(input_grid, list(row).index(v), 0))  # This is wrong, need to track position
    output_neighbor.append(new_row)

# Correct version
output_neighbor = []
for r in range(7):
    new_row = []
    for c in range(7):
        v = input_grid[r][c]
        if v == 1:
            new_row.append(1)
        elif v == 0:
            new_row.append(0)
        else:
            new_row.append(count_1_neighbors(input_grid, r, c))
    output_neighbor.append(new_row)

print("\nNeighbor-based (count of adjacent 1s):")
for row in output_neighbor:
    print(' '.join(f'{v:2}' for v in row))

